   365      p = t + 1;    /* skip '%' */
   366
   367      width = prec = -1;
   368      nextvalue = mrb_undef_value();
   369
   370  retry:
   371      switch (*p) {
   372        default:
   373          mrb_raisef(mrb, E_ARGUMENT_ERROR, "malformed format string - %%%c", *p);
   374          break;
   375
   376        case ' ':
   377          CHECK_FOR_FLAGS(flags);
   378          flags |= FSPACE;
   379          p++;
   380          goto retry;
   381
   382        case '#':
   383          CHECK_FOR_FLAGS(flags);
   384          flags |= FSHARP;
   385          p++;
   386          goto retry;
   387
   388        case '+':
   389          CHECK_FOR_FLAGS(flags);
   390          flags |= FPLUS;
   391          p++;
   392          goto retry;
   393
   394        case '-':
   395          CHECK_FOR_FLAGS(flags);
   396          flags |= FMINUS;
   397          p++;
   398          goto retry;
   399
   400        case '0':
   401          CHECK_FOR_FLAGS(flags);
   402          flags |= FZERO;
   403          p++;
   404          goto retry;
   405
   406        case '1': case '2': case '3': case '4':
   407        case '5': case '6': case '7': case '8': case '9':
